class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        # Create a dictionary to group elements by their diagonal key (i + j)
        diagonal_dict = {}

        # Fill the dictionary with elements and their diagonal key
        for i in range(n):
            for j in range(n):
                key = i + j
                if key not in diagonal_dict:
                    diagonal_dict[key] = []
                diagonal_dict[key].append(grid[i][j])

        # Reassign the sorted elements back to the matrix
        for i in range(n):
            for j in range(n):
                key = i + j
                if key in diagonal_dict:
                    if key < n:  # Bottom-left triangle: non-increasing
                        sorted_diag = sorted(diagonal_dict[key], reverse=True)
                    else:  # Top-right triangle: non-decreasing
                        sorted_diag = sorted(diagonal_dict[key])
                    # Put the sorted elements back in the correct positions
                    # To do this, we need to know the original positions of the elements in the diagonal
                    # This part is more complex. We need to collect the positions of the elements in the diagonal
                    # and assign the sorted values back.

        # Rebuild the matrix correctly by traversing the diagonals again
        # This is an alternative approach for clarity and correctness
        matrix = [[0] * n for _ in range(n)]
        # Collect all diagonals again
        diagonals = [[] for _ in range(2 * n - 1)]
        for i in range(n):
            for j in range(n):
                key = i + j
                diagonals[key].append((i, j, grid[i][j]))

        # Sort each diagonal according to its position
        for key in range(2 * n - 1):
            diag = diagonals[key]
            if key < n:
                # Bottom-left triangle: non-increasing
                sorted_diag = sorted(diag, key=lambda x: (-x[2], x[0], x[1]))
            else:
                # Top-right triangle: non-decreasing
                sorted_diag = sorted(diag, key=lambda x: (x[2], x[0], x[1]))

            # Place the sorted elements back into the matrix
            for item in sorted_diag:
                i, j, val = item
                matrix[i][j] = val

        return matrix

