class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)

        # Helper function to get the diagonal elements and their positions
        def get_diagonal_elements(sum_val, is_bottom_left):
            elements = []
            positions = []
            if is_bottom_left:
                # Bottom-left triangle (sum >= n - 1)
                for i in range(n):
                    j = sum_val - i
                    if 0 <= j < n:
                        elements.append(grid[i][j])
                        positions.append((i, j))
            else:
                # Top-right triangle (sum < n - 1)
                for i in range(n):
                    j = sum_val - i
                    if 0 <= j < n:
                        elements.append(grid[i][j])
                        positions.append((i, j))
            return elements, positions

        # Process bottom-left diagonals (sum >= n - 1)
        for s in range(n - 1, 2 * n - 2):
            elements, positions = get_diagonal_elements(s, True)
            # Sort in non-increasing order
            elements.sort(reverse=True)
            # Place back into the grid
            for i, (r, c) in enumerate(positions):
                grid[r][c] = elements[i]

        # Process top-right diagonals (sum < n - 1)
        for s in range(0, n - 1):
            elements, positions = get_diagonal_elements(s, False)
            # Sort in non-decreasing order
            elements.sort()
            # Place back into the grid
            for i, (r, c) in enumerate(positions):
                grid[r][c] = elements[i]

        return grid

