class Solution:
    def minTime(self, skill: List[int], mana: List[int]) -> int:
        # Precompute the total time for each potion
        potion_time = [sum(s * m for s in skill) for m in mana]

        # Start with 0 time for the first potion
        start_time = 0

        for time in potion_time:
            start_time += time

        return start_time

