class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        from itertools import product

        def is_palindrome(string):
            return string == string[::-1]

        max_len = 0

        # Try all possible substrings from s and t
        n, m = len(s), len(t)

        # Iterate over all possible substrings of s
        for i in range(n):
            for j in range(i, n):
                sub_s = s[i:j+1]

                # Iterate over all possible substrings of t
                for k in range(m):
                    for l in range(k, m):
                        sub_t = t[k:l+1]
                        combined = sub_s + sub_t
                        if is_palindrome(combined):
                            max_len = max(max_len, len(combined))

        # Also consider the case where we take only one of the strings
        # (i.e., just the max palindrome from s or from t)
        max_s_pal = max([len(x) for x in [s[i:j+1] for i in range(n) for j in range(i, n)] if is_palindrome(x)], default=0)
        max_t_pal = max([len(x) for x in [t[i:j+1] for i in range(m) for j in range(i, m)] if is_palindrome(x)], default=0)
        max_len = max(max_len, max_s_pal, max_t_pal)

        return max_len

