class Solution:
    def lastMarkedNodes(self, edges: List[List[int]]) -> List[int]:
        n = len(edges) + 1
        # Build adjacency list
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        # Helper function to find the furthest node from a starting node and its distance
        def bfs(start):
            visited = {start: 0}
            queue = deque([start])
            max_dist = 0
            farthest_node = start
            while queue:
                node = queue.popleft()
                for neighbor in graph[node]:
                    if neighbor not in visited:
                        visited[neighbor] = visited[node] + 1
                        queue.append(neighbor)
                        if visited[neighbor] > max_dist:
                            max_dist = visited[neighbor]
                            farthest_node = neighbor
            return farthest_node, max_dist

        result = []
        for i in range(n):
            farthest_node, _ = bfs(i)
            result.append(farthest_node)

        return result

