    def smallestNumber(self, num: str, t: int) -> str:
        def is_zero_free(s: str) -> bool:
            return '0' not in s

        def product_of_digits(s: str) -> int:
            prod = 1
            for c in s:
                digit = int(c)
                if digit == 0:
                    return 0
                prod *= digit
            return prod

        def increment_string(s: str) -> str:
            s_list = list(s)
            i = len(s_list) - 1
            while i >= 0 and s_list[i] == '9':
                s_list[i] = '0'
                i -= 1
            if i < 0:
                return '1' + '0' * len(s_list)
            s_list[i] = str(int(s_list[i]) + 1)
            return ''.join(s_list)

        # Check the original number
        if is_zero_free(num):
            if product_of_digits(num) % t == 0:
                return num
        else:
            # Original number has zero, so we cannot consider it
            pass

        # Try to find the smallest number >= num that is zero-free and has product of digits divisible by t
        max_tries = 1000  # Arbitrary limit to avoid infinite loops for some inputs
        for i in range(1, max_tries + 1):
            candidate = increment_string(num)
            if is_zero_free(candidate):
                prod = product_of_digits(candidate)
                if prod % t == 0:
                    return candidate
            else:
                continue
            num = candidate  # Move to the next candidate

        return "-1"

