    def maxFrequency(self, nums: List[int], k: int, numOperations: int) -> int:
        nums.sort()
        n = len(nums)
        max_freq = 0

        # Sliding window approach to find the largest window where all elements can be adjusted to the max of the window
        left = 0
        for right in range(n):
            # Expand the window until the number of operations needed is within the allowed
            while right - left + 1 > 0:
                current_max = nums[right]
                # Calculate total cost to bring all elements in the window to current_max
                total_ops = 0
                for i in range(left, right + 1):
