class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        # Convert the string to a list for easier manipulation
        s = list(s)

        # Convert the string into a list of integers for easier processing
        s_list = [int(c) for c in s]

        # Function to get the maximum run length of same characters
        def max_run_length(arr):
            max_len = 0
            current_len = 1
            for i in range(1, len(arr)):
                if arr[i] == arr[i - 1]:
                    current_len += 1
                    max_len = max(max_len, current_len)
                else:
                    current_len = 1
            return max_len

        # Function to find the positions to flip to minimize the longest run
        # This is a simplified version for the given constraints
        def optimal_flips():
            # We can simulate flipping to break the longest runs
            flips = 0
            i = 0
            n = len(s_list)

            # Try to merge adjacent same characters
            while flips < numOps:
                # Find the longest run of the same character
                max_len = 0
                max_index = -1
                run_start = 0
                current_char = s_list[0]
                for j in range(n):
                    if s_list[j] == current_char:
                        current_len = 1
                        for k in range(j + 1, n):
                            if s_list[k] == current_char:
                                current_len += 1
                            else:
                                break
                        if current_len > max_len:
                            max_len = current_len
                            max_index = j
                            max_char = current_char
                    else:
                        current_char = s_list[j]
                        run_start = j
                # If no run is found, break
                if max_len == 0:
                    break

                # Flip the middle of the run to break it
                if max_len > 1:
                    flip_pos = max_index + max_len // 2
                    if flip_pos < n:
                        s_list[flip_pos] = 1 - s_list[flip_pos]
                        flips += 1

            return max_run_length(s_list)

        result = optimal_flips()
        return result

