import heapq
from typing import List

class Solution:
    def shortestDistanceAfterQueries(self, n: int, queries: List[List[int]]) -> List[int]:
        def dijkstra(start, end, graph):
            # Build adjacency list
            adj = {i: [] for i in range(n)}
            for u, v in graph:
                adj[u].append(v)
            # Dijkstra's algorithm
            dist = [float('inf')] * n
            dist[start] = 0
            heap = [(0, start)]
            visited = set()

            while heap:
                d, u = heapq.heappop(heap)
                if u in visited:
                    continue
                visited.add(u)
                if u == end:
                    break
                for v in adj[u]:
                    if dist[v] > d + 1:
                        dist[v] = d + 1
                        heapq.heappush(heap, (dist[v], v))
            return dist[end]

        # Initialize the graph with only the initial roads
        initial_graph = []
        for i in range(n - 1):
            initial_graph.append((i, i + 1))

        result = []
        current_graph = initial_graph.copy()

        for query in queries:
            # Add the new road to the graph
            current_graph.append(query)
            # Compute shortest distance after adding the query
            shortest = dijkstra(0, n - 1, current_graph)
            result.append(shortest)

        return result

