import heapq
from typing import List

class Solution:
    def shortestDistanceAfterQueries(self, n: int, queries: List[List[int]]) -> List[int]:
        def dijkstra(adj, n):
            dist = [float('inf')] * n
            dist[0] = 0
            heap = [(0, 0)]
            while heap:
                current_dist, u = heapq.heappop(heap)
                if u == n - 1:
                    return current_dist
                if current_dist > dist[u]:
                    continue
                for v, w in adj[u]:
                    if dist[v] > dist[u] + w:
                        dist[v] = dist[u] + w
                        heapq.heappush(heap, (dist[v], v))
            return dist[n - 1]

        # Initialize the adjacency list with the initial roads (0 -> 1, 1 -> 2, ..., n-2 -> n-1)
        adj = [[] for _ in range(n)]
        for i in range(n - 1):
            adj[i].append((i + 1, 1))  # weight is 1

        result = []

        # Run Dijkstra once initially
        initial_dist = dijkstra(adj, n)
        result.append(initial_dist)

        # Process each query
        for u, v in queries:
            adj[u].append((v, 1))  # add new road
            current_dist = dijkstra(adj, n)
            result.append(current_dist)

        return result

