class Solution:
    def answerString(self, word: str, numFriends: int) -> str:
        from itertools import combinations

        n = len(word)
        max_string = ""

        # Function to split word into parts with numFriends parts and collect all parts
        def generate_splits(start, parts, current_parts):
            if len(current_parts) == numFriends:
                # Add all parts to the list of possible strings
                for part in current_parts:
                    nonlocal max_string
                    if part > max_string:
                        max_string = part
                return

            if start >= n:
                return

            # Try all possible end positions for the next part
            for end in range(start + 1, n + 1):
                next_part = word[start:end]
                if len(current_parts) + 1 <= numFriends:
                    generate_splits(end, parts, current_parts + [next_part])

        generate_splits(0, [], [])

        return max_string

