class Solution:
    def numberOfSubstrings(self, s: str, k: int) -> int:
        from collections import defaultdict

        n = len(s)
        total_substrings = n * (n + 1) // 2

        # Function to check if a window is valid (i.e., all characters appear less than k times)
        def is_invalid(window_counts):
            for count in window_counts.values():
                if count >= k:
                    return False
            return True

        # Sliding window approach to count all substrings that are invalid (i.e., no character appears >= k times)
        def count_invalid_substrings():
            left = 0
            window_counts = defaultdict(int)
            invalid_count = 0

            for right in range(n):
                window_counts[s[right]] += 1

                # While current window is invalid, move left to reduce the window size
                while not is_invalid(window_counts) and left <= right:
                    if window_counts[s[left]] == 1:
                        del window_counts[s[left]]
                    else:
                        window_counts[s[left]] -= 1
                    left += 1

                # Add all substrings ending at 'right' that start from left to right
                invalid_count += left  # because the substrings are [left, right], [left+1, right], ..., [right, right]

            return invalid_count

        invalid = count_invalid_substrings()
        return total_substrings - invalid

