    def countGoodIntegers(self, n: int, k: int) -> int:
        from itertools import permutations

        def is_palindrome(s):
            return s == s[::-1]

        def is_divisible_by_k(s, k):
            return int(s) % k == 0

        def generate_palindromes(n, k):
            # Generate all possible palindromes of n digits that are divisible by k
            palindromes = set()
            if n == 1:
                for d in range(1, 10):
                    if d % k == 0:
                        palindromes.add(str(d))
                return palindromes
            else:
                half_len = (n + 1) // 2
                for prefix in range(10 ** (half_len - 1), 10 ** half_len):
                    # Convert prefix to string
                    prefix_str = str(prefix)
                    if n % 2 == 0:
                        # Even length: mirror prefix
                        pal_str = prefix_str + prefix_str[::-1]
                    else:
                        # Odd length: mirror prefix without last digit
                        pal_str = prefix_str + prefix_str[:-1][::-1]
                    if len(pal_str) != n:
                        continue
                    if int(pal_str) % k == 0:
                        palindromes.add(pal_str)
                return palindromes

        def count_permutations(pal_str):
            # Count the number of n-digit integers that are permutations of pal_str
            # and don't have leading zeros
            digits = list(pal_str)
            total_perms = 0

            # Handle permutations of digits
            seen = set()
            for perm in permutations(digits):
                perm_str = ''.join(perm)
                if perm_str[0] == '0':
                    continue
                if perm_str not in seen:
                    seen.add(perm_str)
                    total_perms += 1
            return total_perms

        # Generate all possible palindromes of length n that are divisible by k
        palindromes = generate_palindromes(n, k)

        # Count all possible good numbers
        total_good = 0
        for pal in palindromes:
            total_good += count_permutations(pal)

        return total_good

