    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        from bisect import bisect_left, bisect_right

        def max_possible_distance():
            return 2 * side  # max possible Manhattan distance between any two boundary points

        def is_possible(target_distance):
            # Sort the points in a way that allows greedy selection
            # For this, we'll sort based on (x + y) and then (x - y) to help in ordering
            points_sorted = sorted(points, key=lambda p: (p[0] + p[1], p[0] - p[1]))
            selected = []
            n = len(points_sorted)
            for p in points_sorted:
                if not selected:
                    selected.append(p)
                else:
                    # Check if the current point is at least target_distance away from all selected points
                    min_dist = float('inf')
                    for s in selected:
                        dist = abs(p[0] - s[0]) + abs(p[1] - s[1])
                        if dist < min_dist:
                            min_dist = dist
                    if min_dist >= target_distance:
                        selected.append(p)
                        if len(selected) == k:
                            return True
            return len(selected) >= k

        # Binary search for the maximum possible minimum distance
        low, high = 0, max_possible_distance()
        answer = 0
        while low <= high:
            mid = (low + high) // 2
            if is_possible(mid):
                answer = mid
                low = mid + 1
            else:
                high = mid - 1
        return answer

