class Solution:
    def countWinningSequences(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s)
        from functools import lru_cache

        # Helper function to compute points for a given (Alice_move, Bob_move)
        def get_points(a_move, b_move):
            if a_move == b_move:
                return 0
            if (a_move == 'F' and b_move == 'E') or (a_move == 'E' and b_move == 'F'):
                return 1
            elif (a_move == 'W' and b_move == 'F') or (a_move == 'F' and b_move == 'W'):
                return 1
            elif (a_move == 'E' and b_move == 'W') or (a_move == 'W' and b_move == 'E'):
                return 1
            else:
                return 0

        # DP state: (position, last_move, diff)
        # last_move: 'F', 'W', or 'E'
        # diff: difference in points (Bob - Alice)
        # Returns the number of valid sequences from this state
        @lru_cache(maxsize=None)
        def dp(pos, last_move, diff):
            if pos == n:
                return 1 if diff > 0 else 0
            total = 0
            for curr_move in ['F', 'W', 'E']:
                if curr_move == last_move:
                    continue  # consecutive same move not allowed
                new_diff = diff + get_points(s[pos], curr_move)
                total += dp(pos + 1, curr_move, new_diff)
                total %= MOD
            return total % MOD

        # Initialize DP with no previous move
        # Start from position 0, no previous move, diff = 0
        result = dp(0, None, 0)
        return result % MOD

