        n = len(s)

        # Define the possible moves and the outcome for each possible pair
        def get_score(a_move, b_move):
            if a_move == b_move:
                return 0
            # Fire vs Earth: Fire wins
            if (a_move == 'F' and b_move == 'E') or (a_move == 'E' and b_move == 'F'):
                return 1
            # Water vs Fire: Water wins
            elif (a_move == 'W' and b_move == 'F') or (a_move == 'F' and b_move == 'W'):
                return 1
            # Earth vs Water: Earth wins
            elif (a_move == 'E' and b_move == 'W') or (a_move == 'W' and b_move == 'E'):
                return 1
            else:
                return 0

        # We'll use memoization with position, last move, and score difference
        from functools import lru_cache

        # Precompute the moves Alice makes for each round
        alice_moves = list(s)

        # Since we can't use lru_cache with mutable types like strings, we'll use a tuple for memoization
        # The moves are F, W, E

        # Let's convert the moves to 0, 1, 2 for easier handling in the DP
        move_to_idx = {'F': 0, 'W': 1, 'E': 2}

        @lru_cache(None)
        def dp(pos, last_move, score_diff):
            if pos == n:
                # At the end, if score_diff > 0, it's a winning sequence
                return 1 if score_diff > 0 else 0
            total = 0
            a_move = alice_moves[pos]
            for current_move in move_to_idx.keys():
                if current_move == last_move:
                    continue  # Can't repeat the same move
                new_score_diff = score_diff + get_score(a_move, current_move)
                total += dp(pos + 1, current_move, new_score_diff)
                total %= MOD
            return total % MOD

        # Start with no previous move, score_diff = 0
        # The initial 'last_move' is represented as -1 (invalid)
        return dp(0, -1, 0) % MOD

