class Solution:
    def countBalancedPermutations(self, num: str) -> int:
        MOD = 10**9 + 7

        from collections import Counter
        from math import factorial

        # Precompute factorials for combinations
        max_len = len(num)
        fact = [1] * (max_len + 1)
        for i in range(1, max_len + 1):
            fact[i] = (fact[i - 1] * i) % MOD

        def nCr(n, r):
            if r < 0 or r > n:
                return 0
            return fact[n] * pow(fact[r], MOD - 2, MOD) % MOD * pow(fact[n - r], MOD - 2, MOD) % MOD

        # Count digit frequency
        freq = Counter(num)
        total_len = len(num)
        total_sum = sum(int(c) for c in num)

        # If total sum is odd, return 0
        if total_sum % 2 != 0:
            return 0

        # The target sum for each part (even and odd indices)
        target = total_sum // 2

        # Use memoization and backtracking to count valid permutations
        memo = {}

        def backtrack(pos, even_sum, odd_sum, used):
            if pos == total_len:
                return 1 if even_sum == odd_sum else 0

            key = (pos, even_sum, odd_sum, tuple(used))
            if key in memo:
                return memo[key]

            res = 0
            for digit in freq:
                if freq[digit] == 0:
                    continue
                if not used[digit] and (pos % 2 == 0 and even_sum + int(digit) <= target) or (pos % 2 == 1 and odd_sum + int(digit) <= target):
                    # Check if we can use this digit
                    if pos % 2 == 0:
                        new_even_sum = even_sum + int(digit)
                        if new_even_sum > target:
                            continue
                    else:
                        new_odd_sum = odd_sum + int(digit)
                        if new_odd_sum > target:
                            continue

                    # Mark the digit as used
                    used[digit] = 1
                    freq[digit] -= 1
                    res += backtrack(pos + 1, new_even_sum if pos % 2 == 0 else even_sum, new_odd_sum if pos % 2 == 1 else odd_sum, used)
                    freq[digit] += 1
                    used[digit] = 0

            memo[key] = res % MOD
            return memo[key]

        # Initialize used as a dictionary of digit counts
        used = {str(d): 0 for d in range(10)}
        for d in freq:
            used[d] = freq[d]

        # Start the backtracking
        return backtrack(0, 0, 0, used) % MOD

