class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        from collections import defaultdict, deque

        n = len(properties)
        if n == 0:
            return 0

        # Helper function to compute the number of common distinct integers between two rows
        def intersect(a, b):
            set_a = set(a)
            set_b = set(b)
            return len(set_a & set_b)

        # Build adjacency list
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(i + 1, n):
                if intersect(properties[i], properties[j]) >= k:
                    graph[i].append(j)
                    graph[j].append(i)

        # BFS to find connected components
        visited = [False] * n
        components = 0

        for i in range(n):
            if not visited[i]:
                components += 1
                queue = deque([i])
                visited[i] = True
                while queue:
                    node = queue.popleft()
                    for neighbor in graph[node]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            queue.append(neighbor)

        return components

