    def countSubstrings(self, s: str) -> int:
        n = len(s)
        total = 0

        # Precompute powers of 10 modulo 9 (to avoid overflow in some cases)
        power10 = [1] * (n + 1)
        for i in range(1, n + 1):
            power10[i] = (power10[i - 1] * 10) % 999999999  # arbitrary large mod for computation

        # Precompute prefix values
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] * 10 + int(s[i])

        # Iterate over each possible end position j
        for j in range(n):
            d = int(s[j])
            if d == 0:
                continue  # last digit is zero, not allowed for divisibility

            # For all possible i from 0 to j
            for i in range(j + 1):
                length = j - i + 1
                value = prefix[j + 1] - prefix[i] * power10[length]
                if value % d == 0:
                    total += 1

        return total

