class Solution:
    def getSum(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)
        if n == 0:
            return 0

        # Precompute prefix sums
        prefix_sum = [0] * (n + 1)
        for i in range(n):
            prefix_sum[i + 1] = prefix_sum[i] + nums[i]

        total = 0

        # Iterate through the array to find increasing and decreasing runs
        i = 0
        while i < n:
            # Start of a run
            j = i
            while j < n - 1 and (nums[j+1] - nums[j] == 1 or nums[j+1] - nums[j] == -1):
                j += 1

            # Now, we have a run from i to j, inclusive. Let's check whether it is strictly increasing or decreasing.
            # Check if it is strictly increasing
            is_increasing = True
            for k in range(i, j):
                if nums[k+1] - nums[k] != 1:
                    is_increasing = False
                    break
            if is_increasing:
                # Compute all possible subsequences in this increasing run
                run_len = j - i + 1
                for l in range(1, run_len + 1):
                    # All l-length subarrays are valid in this run
                    # Total number is (run_len - l + 1) possible subarrays
                    total += (run_len - l + 1) * (prefix_sum[i + l] - prefix_sum[i])
            else:
                # Check if strictly decreasing
                is_decreasing = True
                for k in range(i, j):
                    if nums[k+1] - nums[k] != -1:
                        is_decreasing = False
                        break
                if is_decreasing:
                    # Compute all possible subsequences in this decreasing run
                    run_len = j - i + 1
                    for l in range(1, run_len + 1):
                        total += (run_len - l + 1) * (prefix_sum[i + l] - prefix_sum[i])

            i = j + 1

        return total % MOD

