class Solution:
    def maxScore(self, nums: List[int]) -> int:
        import math
        from functools import reduce

        def gcd(a, b):
            return math.gcd(a, b)

        def lcm(a, b):
            return a * b // gcd(a, b)

        def compute_gcd_list(lst):
            return reduce(gcd, lst)

        def compute_lcm_list(lst):
            if not lst:
                return 0
            return reduce(lcm, lst)

        n = len(nums)

        if n == 0:
            return 0

        max_score = 0

        # Case 1: do not remove any element
        current_gcd = compute_gcd_list(nums)
        current_lcm = compute_lcm_list(nums)
        if current_gcd != 0 and current_lcm != 0:
            score = current_gcd * current_lcm
            max_score = max(max_score, score)

        # Case 2: remove one element and compute the score
        for i in range(n):
            # Create a new list without the i-th element
            sub_nums = nums[:i] + nums[i+1:]
            if not sub_nums:
                continue

            current_gcd = compute_gcd_list(sub_nums)
            current_lcm = compute_lcm_list(sub_nums)
            if current_gcd != 0 and current_lcm != 0:
                score = current_gcd * current_lcm
                max_score = max(max_score, score)

        # Also consider the case where removing one element results in a single element
        for num in nums:
            score = num * num
            max_score = max(max_score, score)

        return max_score

