    def lengthAfterTransformations(self, s: str, t: int) -> int:
        MOD = 10**9 + 7

        def transform_length(c, t):
            if c == 'z':
                # After t transformations, 'z' becomes a string that grows exponentially
                # The length is 2 * (2^t - 1) + 1
                # Because it becomes "ab", "bc", "cd", ..., and each step doubles the length
                # So total is 2 * (2^t - 1) + 1
                return (2 * (pow(2, t, MOD) - 1) + 1) % MOD
            else:
                return 1  # Each character contributes 1 character after t transformations

