    def minRunesToAdd(self, n: int, crystals: List[int], flowFrom: List[int], flowTo: List[int]) -> int:
        from collections import defaultdict, deque

        # Build the graph
        graph = defaultdict(list)
        reverse_graph = defaultdict(list)
        for f, t in zip(flowFrom, flowTo):
            graph[f].append(t)
            reverse_graph[t].append(f)

        # Step 1: Find strongly connected components (SCCs)
        # Using Kosaraju's algorithm
        visited = set()
        order = []

        def dfs1(node):
            stack = [(node, False)]
            while stack:
                current, processed = stack.pop()
                if processed:
                    order.append(current)
                    continue
                if current in visited:
                    continue
                visited.add(current)
                stack.append((current, True))
                for neighbor in graph[current]:
                    if neighbor not in visited:
                        stack.append((neighbor, False))

        for i in range(n):
            if i not in visited:
                dfs1(i)

        # Second pass to get SCCs
        visited = set()
        sccs = []
        component = [0] * n  # component ID of each node
        current_component = 0

        def dfs2(node, comp):
            stack = [node]
            visited.add(node)
            component[node] = comp
            while stack:
                current = stack.pop()
                for neighbor in reverse_graph[current]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        component[neighbor] = comp
                        stack.append(neighbor)

        for node in reversed(order):
            if node not in visited:
                dfs2(node, current_component)
                current_component += 1
        num_sccs = current_component

        # Step 2: Mark components that contain crystals
        crystal_components = set()
        for crystal in crystals:
            crystal_components.add(component[crystal])

        # Step 3: For each component, check if it has a crystal
        # And also check if it's reachable from any crystal component
        # We need to find the components that are not reachable from any crystal component
        # and are not already connected to a crystal component

        # Build a reachability map from component to component
        # Build adjacency list for component graph
        comp_graph = defaultdict(list)
        for u in range(n):
            for v in graph[u]:
                if component[u] != component[v]:
                    comp_graph[component[u]].append(component[v])

        # Create a reachability map (component -> set of reachable components)
        from collections import deque

        # Build reachability from all crystal components
        reach_from_crystals = defaultdict(set)
        for comp in crystal_components:
            visited_comp = set()
            queue = deque([comp])
            visited_comp.add(comp)
            while queue:
                curr = queue.popleft()
                for neighbor in comp_graph[curr]:
                    if neighbor not in visited_comp:
                        visited_comp.add(neighbor)
                        queue.append(neighbor)
                reach_from_crystals[comp].update(visited_comp)

        # All components that are not in any of the reachable sets from crystal components
        # are those that need to be connected from some crystal component
        required_components = set()
        for comp in range(num_sccs):
            has_crystal = comp in crystal_components
            if not has_crystal:
                reachable = False
                for comp2 in crystal_components:
                    if comp in reach_from_crystals[comp2]:
                        reachable = True
                        break
                if not reachable:
                    required_components.add(comp)

        # The number of required edges is the number of such components that are not connected
        # and need to be connected from some source component with a crystal
        return len(required_components)

