class Solution:
    def minCost(self, nums: List[int]) -> int:
        from functools import lru_cache

        n = len(nums)

        @lru_cache(None)
        def dp(i):
            if i >= n:
                return 0
            if n - i <= 3:
                return max(nums[i:])
            min_cost = float('inf')
            # Try all combinations of removing two elements from first three
            # Consider possible pairs: (0,1), (0,2), (1,2)
            # We will simulate the removal and then proceed from the next index
            # After removal, the new array is formed and the next index is i+1 or i+2 or i+3, depending on removal
            # But instead of modifying the array, we simulate the effect by passing the next index and the remaining elements

            # Option 1: Remove elements at i and i+1
            if i + 1 < n:
                cost = max(nums[i], nums[i+1])
                # After removing these two elements, the next index is i+2
                new_cost = cost + dp(i + 2)
                min_cost = min(min_cost, new_cost)

            # Option 2: Remove elements at i and i+2
            if i + 2 < n:
                cost = max(nums[i], nums[i+2])
                new_cost = cost + dp(i + 1)
                min_cost = min(min_cost, new_cost)

            # Option 3: Remove elements at i+1 and i+2
            if i + 2 < n:
                cost = max(nums[i+1], nums[i+2])
                new_cost = cost + dp(i + 3)
                min_cost = min(min_cost, new_cost)

            return min_cost

        return dp(0)

