        from collections import Counter
        from math import gcd

        total_length = len(s)
        char_counts = Counter(s)
        unique_chars = len(char_counts)

        if unique_chars == 1:
            return 0  # Already all characters the same

        min_ops = float('inf')

        # We can try all possible target counts (number of characters per unique type)
        # The target count must be such that total_length is divisible by target_count
        # and target_count must be at least 1 and at most total_length // unique_chars
        # We look for possible values of target_count that divide total_length
