    def maxDifference(self, s: str, k: int) -> int:
        from collections import defaultdict

        n = len(s)
        max_diff = -1

        # Helper function to check if a window has at least one odd and one even frequency
        def has_odd_even(freq_dict):
            has_odd = False
            has_even = False
            for count in freq_dict.values():
                if count % 2 == 1:
                    has_odd = True
                else:
                    has_even = True
            return has_odd and has_even

        # Iterate over all possible substrings of length >= k
        for i in range(n):
            for j in range(i + k - 1, n):
                # Extract substring from i to j inclusive
                substring = s[i:j+1]
                freq = defaultdict(int)
                for c in substring:
                    freq[c] += 1
                if has_odd_even(freq):
                    # Find the max freq of odd, and min freq of even
                    odd_freqs = [f for f in freq.values() if f % 2 == 1]
                    even_freqs = [f for f in freq.values() if f % 2 == 0]
                    if odd_freqs and even_freqs:
                        max_odd = max(odd_freqs)
                        min_even = min(even_freqs)
                        current_diff = max_odd - min_even
                        if current_diff > max_diff:
                            max_diff = current_diff

        return max_diff

