    def maxDifference(self, s: str, k: int) -> int:
        from collections import defaultdict

        n = len(s)

        # Function to count frequencies of characters in a substring
        def get_freq(sub):
            freq = defaultdict(int)
            for ch in sub:
                freq[ch] += 1
            return freq

        max_diff = -1

        # Iterate over all possible substrings of length >= k
        # Since the problem allows for any length >= k, but we can optimize by trying substrings of length k and then expanding

        for i in range(n - k + 1):
            # Try substrings starting at i with length k, then maybe k+1, etc.
            for length in range(k, min(n - i + 1, k + 2)):  # Try up to k+1
