    def shiftDistance(self, s: str, t: str, nextCost: List[int], previousCost: List[int]) -> int:
        def get_cost(s_char, t_char, nextCost, previousCost):
            # Convert characters to their respective indices
            s_idx = ord(s_char) - ord('a')
            t_idx = ord(t_char) - ord('a')

            if s_idx == t_idx:
                return 0

            # Move forward: (s_idx to t_idx) % 26
            forward_steps = (t_idx - s_idx + 26) % 26
            forward_cost = forward_steps * nextCost[s_idx]

            # Move backward: (s_idx to t_idx) in reverse, which is (26 - forward_steps) % 26
            backward_steps = (26 - forward_steps) % 26
            backward_cost = backward_steps * previousCost[s_idx]

            # Return the minimum of forward and backward cost
            return min(forward_cost, backward_cost)

        total_cost = 0
        for sc, tc in zip(s, t):
            total_cost += get_cost(sc, tc, nextCost, previousCost)

        return total_cost

