class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        from collections import defaultdict

        if k == 0:
            return True

        n = len(s)
        if n < 2:
            return False

        # Preprocess character positions
        char_positions = defaultdict(list)
        for idx, c in enumerate(s):
            char_positions[c].append(idx)

        # Function to check if a substring is special
        def is_special(sub):
            chars = set(sub)
            for c in chars:
                if any(pos not in range(len(sub)) for pos in char_positions[c]):
                    return False
            return True

        # Find all possible special substrings
        special_substrings = []

        # We can iterate over possible substrings in the string and collect valid ones
        # However, for efficiency, we focus on minimal possible special substrings

        # First, check if any single character is special.
        # A single character is special if it appears only once in the string.

        # For all possible substrings of length 2 or more, collect the ones that are special

        def collect_special_substrings():
            special = set()
            n = len(s)
            for i in range(n):
                for j in range(i + 1, n):
                    substr = s[i:j]
                    if len(substr) < 2:
                        continue
                    # Check if the substring is special
                    if is_special(substr):
                        # Check if the substring is not the entire string
                        if substr != s:
                            special.add((i, j, substr))
            return special

        # Collect all valid special substrings
        valid_special_substrings = collect_special_substrings()

        # Now, find the maximum number of non-overlapping special substrings
        # We'll use a greedy approach to find the maximum number possible
        # Sort the substrings by their end position
        sorted_subs = sorted(valid_special_substrings, key=lambda x: x[1])

        count = 0
        last_end = -1

        for start, end, substr in sorted_subs:
            if start > last_end:
                count += 1
                last_end = end
                if count == k:
                    return True

        return count >= k

